import{_ as o,o as t,c as d,a5 as c}from"./chunks/framework.DSg0KOwT.js";const u=JSON.parse('{"title":"Detector contract","description":"","frontmatter":{},"headers":[],"relativePath":"contributor-guide/architecture/detector-contract.md","filePath":"contributor-guide/architecture/detector-contract.md"}'),s={name:"contributor-guide/architecture/detector-contract.md"};function r(a,e,n,i,h,l){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="detector-contract" tabindex="-1">Detector contract <a class="header-anchor" href="#detector-contract" aria-label="Permalink to &quot;Detector contract&quot;">​</a></h1><p><code>packages/core/src/detectors.ts</code> assembles <code>DETECTORS</code>, the single source of Spark-optimization logic: one declarative entry per pattern, each declared in its own folder, <code>packages/core/src/detectors/&lt;type&gt;/detect.ts</code> (see <a href="#module-layout">Module layout</a>) and each carrying <code>type</code>, <code>scope</code> (<code>stage</code> / <code>app</code> / <code>config</code> / <code>sql</code>), <code>order</code>, <code>fixEffort</code>, <code>version</code>, a <code>thresholds</code> object, an <code>emits</code> list, an optional <code>docAnchor</code> (every entry but <code>incompleteRun</code> sets one), optional <code>inScorecard</code>, <code>property</code> and <code>suppressedBy</code>, and co-located <code>detect()</code> and <code>estimate()</code> functions. Each finding&#39;s <code>impactBand</code> and recommendation copy are set inside <code>detect()</code>, and so is its <code>remediation</code>: the structured <code>{kind: &#39;conf&#39;, key, direction, suggested}</code> form of the Spark properties that copy names (<code>increaseConf</code>, <code>decreaseConf</code> and <code>setConf</code> in <code>packages/core/src/remediation.ts</code>). A detector adds an entry only for a property its recommendation already names, and leaves <code>suggested</code> null unless it computes the value itself. Entries apply together unless the recommendation words them as alternatives (&quot;either ... or&quot;): <code>idleCapacityFix</code> in <code>detectors/fixes.ts</code> gives an idle-capacity finding with dynamic allocation off the alternatives <code>set spark.dynamicAllocation.enabled</code> and <code>decrease spark.executor.instances</code>, and with it on <code>decrease spark.dynamicAllocation.maxExecutors</code> plus <code>decrease spark.dynamicAllocation.minExecutors</code> when the logged floor is above 0. <code>Remediation</code> is a union: <code>codeFix(hint)</code> builds the <code>{kind: &#39;code&#39;, hint}</code> entry for a fix no property makes, which the skew family emits when its origin is <code>other</code> or skew-join handling is on and <code>aqe-skew.ts</code> finds the job&#39;s code is what has to change. Code that reads <code>key</code> checks <code>kind</code> first.</p><p>Each entry is built by the helper for its scope (<code>detectors/define.ts</code>): <code>defineStageDetector</code>, <code>defineSqlDetector</code>, <code>defineAppDetector</code> or <code>defineConfigDetector</code>. The helper sets <code>scope</code>, infers the thresholds type from the entry&#39;s own <code>thresholds</code> literal, and types <code>detect</code> as a function property, so its parameters are checked strictly rather than bivariantly:</p><table tabindex="0"><thead><tr><th>Scope</th><th><code>detect</code> signature</th></tr></thead><tbody><tr><td><code>stage</code></td><td><code>detect(stage, ctx, thresholds)</code></td></tr><tr><td><code>sql</code></td><td><code>detect(sqlExec, ctx, thresholds)</code></td></tr><tr><td><code>app</code></td><td><code>detect(ctx, thresholds)</code></td></tr><tr><td><code>config</code></td><td><code>detect(target, thresholds)</code>, where <code>target</code> is <code>{ app }</code></td></tr></tbody></table><p><code>ctx</code> (<code>DetectorCtx</code>) is required, and its <code>app</code> is nullable as on <code>AppModel.app</code>, so a detector that reads the app without a guard, reads a threshold its entry doesn&#39;t declare, or expects another scope&#39;s target fails to compile. <code>detect</code> never reads <code>this</code>. The helper freezes the entry&#39;s <code>thresholds</code> and adds <code>withThresholds(overrides?)</code>, which returns <code>detect</code> with the thresholds bound: the entry&#39;s own, or the caller&#39;s overrides merged over them (see <a href="#tuning-thresholds">Tuning thresholds</a>). Runners such as <code>analyze()</code> call only that.</p><p><code>estimate(finding, ctx)</code> prices one of the entry&#39;s own findings: <code>finding</code> is typed as the <code>Finding</code> member of a type the entry <code>emits</code>, and <code>ctx</code> (<code>EstimateCtx</code>: <code>stages</code>, <code>occupancy</code>, <code>totalCores</code>) is the one occupancy sweep <code>analyze()</code> builds per run. It returns an <code>ImpactEstimate</code> or null (see <a href="./impact-estimation.html">Impact estimation</a>). Every entry must declare one; an entry with no waste model passes <code>noWasteModel</code>. <code>estimateImpact()</code> runs it after suppression, keyed by emitted type. The same <code>EstimateCtx</code> reaches <code>detect()</code> as <code>ctx.impact</code>, so a runtime floor can gate on the estimate the finding will display: <code>skew</code> and <code>straggler</code> build their tail claim once (<code>skewTailClaim</code>/<code>stragglerTailClaim</code>) and both their floor and their <code>estimate()</code> read it through <code>tailClaimImpact</code>. Shared model constants and helpers live in <code>packages/core/src/impact-model.ts</code>.</p><p><code>DETECTORS</code> (<code>detectors.ts</code>) is declared <code>as const satisfies readonly Detector[]</code>, so each entry keeps its literal <code>type</code> and <code>emits</code>. Two unions derive from it: <code>DetectorType</code> (every entry&#39;s own <code>type</code>) and <code>FindingType</code> (every type an entry&#39;s <code>emits</code> lists, the finding types that actually appear on findings). <code>emits</code> is <code>[type]</code> for every entry except <code>broadcastSizing</code>, whose one plan walk emits <code>overBroadcast</code> and <code>underBroadcast</code> and never its own name. Every per-type lookup keys on the emitted <code>FindingType</code>, never on <code>DetectorType</code>: code that needs the emitted types of an entry reads its <code>emits</code> list. Code that iterates entries generically, such as <code>analyze()</code>, reads them through the <code>Detector</code> type, a union over scopes with the thresholds type erased, <code>detect</code> left off and <code>estimate</code> taking any <code>Finding</code>, so switching on <code>scope</code> narrows the bound function <code>withThresholds()</code> returns.</p><p>How a finding type is presented is registered once, in the <code>presentation</code> export of its folder&#39;s <code>presentation.ts</code>. <code>FINDING_PRESENTATION</code> (<code>packages/core/src/finding-presentation.ts</code>) assembles the rows, typed <code>{ [T in FindingType]: FindingPresentation&lt;T&gt; }</code> so the compiler requires exactly one row per emitted type. A row holds the type&#39;s <code>name</code>, board <code>tag</code>, <code>actionLabel(finding)</code>, <code>genericRecommendation(finding)</code> and <code>thresholdSummary(thresholds)</code>, each finding argument typed as that type&#39;s <code>Finding</code> member and <code>thresholds</code> as the emitting entry&#39;s own <code>thresholds</code>. <code>FINDING_NAMES</code>, <code>TYPE_TAG_MAP</code>, <code>getThresholdSummary</code>, <code>findingActionLabel</code> and <code>coreFindingGenericRecommendation</code> all read it. The rows sit beside the <code>DETECTORS</code> entries rather than on them because the HTML export renders names, tags and labels but may not reach <code>detectors.ts</code> or a folder&#39;s <code>detect.ts</code> (see <a href="./state-and-history.html#run-interpretation">Run interpretation</a>); a <code>presentation.ts</code> imports detector code only as types, and the helpers its rows share are in <code>detectors/presentation-shared.ts</code>. A detector&#39;s <code>scope</code> and <code>order</code> reach renderers through <code>detectorInfoByType()</code> (<code>detector-docs.ts</code>), keyed by emitted type, which the run interpretation ships; the Alerts clean-check grouping reads <code>detectors[type].scope</code>.</p><p>Each finding type has its own shape in its folder&#39;s <code>detect.ts</code>: <code>finding-types.ts</code> assembles <code>Finding</code>, a union discriminated on <code>type</code>, from each folder&#39;s <code>Emits</code> (through its type-only <code>emits</code> export), and a compile-time check in <code>detectors.ts</code> fails when its members and <code>FindingType</code> differ. Each member splits into a <code>&lt;Type&gt;Evidence</code> interface, the fields the evidence report publishes (listed again in the folder&#39;s <code>evidenceKeys</code>, checked both ways), and fields declared only on <code>&lt;Type&gt;Finding</code>, which other core modules read but the report never publishes. <code>value</code> is always a magnitude; a text-valued finding (<code>stageFailed</code>, <code>configAudit</code>, <code>incompleteRun</code>) sets <code>valueText</code> instead. So a new detector type is one folder, <code>packages/core/src/detectors/&lt;type&gt;/</code>. Its <code>detect.ts</code> holds the <code>DETECTORS</code> entry (with its <code>emits</code> list and an <code>estimate()</code> that covers it), the finding members with their <code>Emits</code>, <code>evidenceKeys</code> and <code>idDiscriminators</code>; its <code>presentation.ts</code> holds the presentation row. Two index files list the folders, one entry each:</p><ul><li><code>detectors/index.ts</code>: the import of <code>detect.ts</code>, the <code>export type</code> line for its finding members, and its place in the list, which is the render order. <code>detectors.ts</code> (<code>DETECTORS</code>), <code>finding-meta.ts</code> (<code>EVIDENCE_KEYS</code> and <code>ID_DISCRIMINATORS</code>) and <code>finding-types.ts</code> (<code>Finding</code>, <code>FindingEvidenceMap</code> and the member re-exports) read it.</li><li><code>detectors/presentations.ts</code>: the import of <code>presentation.ts</code> and its place in the list. <code>finding-presentation.ts</code> (<code>FINDING_PRESENTATION</code>) reads it.</li></ul><p>The <code>presentation.ts</code> also goes on <code>ALLOWED_EXPORT_CORE_MODULES</code> in <code>scripts/export-analysis-guard.mjs</code>, because the HTML export renders its row. The view adds a <code>REGISTRY</code> entry with its row model (see <a href="./widget-rendering/finding-widget-shell.html">Finding widget shell</a>). The compiler reports each one that is missing. Tests and process, not the compiler, cover the rest: a new board tag goes in AGENTS.md&#39;s tag list (<code>packages/core/test/tag-vocabulary.test.js</code> fails otherwise), an intended finding change is checked with <code>node dev/bench-analyze.mjs --check dev/corpus-snapshot.json</code> and then <code>--update</code>d, and the PR needs a <code>.changeset/*.md</code>. A <code>docAnchor</code> must have a section in the detection docs (<code>packages/core/test/docs-config.test.js</code>). The view narrows with <code>findingsOfType(catalog, type)</code> (<code>packages/core/src/findings-of-type.ts</code>) rather than re-declaring a finding&#39;s fields.</p><p>Both consumers are thin loops over that array:</p><ul><li><p><code>packages/core/src/analyzer.ts</code>: <code>analyze()</code> runs every entry regardless of scope, skipping only <code>inScorecard:false</code> ones, then applies <code>suppressedBy</code> (below); <code>auditConfig()</code> separately runs the <code>scope:&#39;config&#39;</code> entries. The three <code>configAudit</code> entries stay out of the bottleneck catalog because each sets <code>inScorecard:false</code>, not because of <code>scope:&#39;config&#39;</code>: a config-scope detector without that flag would run through <code>analyze()</code> too. Each finding is stamped with its entry&#39;s <code>docAnchor</code>.</p></li><li><p><code>src/view/detector-registry.tsx</code>: <code>REGISTRY</code> maps each emitted finding type to <code>{component, region, widgetId, routeable}</code> (view-only concerns), checked with <code>satisfies Record&lt;FindingType, RegistryEntry&gt;</code>. Each type has its own component, and no two entries share one. The executor-count chart (<code>ExecutorCountChart</code>) is a <code>ReferenceSection</code> tile, not a <code>REGISTRY</code> entry. <code>orderedWidgets(detectors)</code> takes the run interpretation&#39;s <code>detectorInfoByType()</code> record (<code>DetectorInfo</code> per type), keeps the types that have a <code>REGISTRY</code> entry, and sorts <code>action</code>-region components before <code>reference</code>-region ones, then by ascending <code>order</code>, using the record&#39;s declaration order to break ties.</p><p>Each widget component receives the full catalog and self-gates when it has nothing to show, rendering <code>null</code> or a muted &quot;no issue&quot; card for the always-visible ones. <code>orderedWidgets()</code> itself has no empty/non-empty branching, since it iterates the static per-type detector info, not the runtime <code>catalog</code>.</p></li></ul><p>Default thresholds live only in each entry&#39;s <code>thresholds</code>; see <a href="./detector-contract/threshold-tables.html#bottleneck-thresholds">Bottleneck thresholds</a>. Only the CLI and the MCP server can override them, per run: see <a href="#tuning-thresholds">Tuning thresholds</a>.</p><h2 id="module-layout" tabindex="-1">Module layout <a class="header-anchor" href="#module-layout" aria-label="Permalink to &quot;Module layout {#module-layout}&quot;">​</a></h2><p><code>detectors.ts</code> holds only the assembled list and what derives from it: <code>DETECTORS</code> (its order is the render order, see <a href="./widget-rendering.html#widget-rendering-order">Widget rendering</a>), <code>ENTRY_BY_TYPE</code>, <code>DetectorType</code>, <code>FindingType</code>, <code>ThresholdsOf</code>, <code>ThresholdOverrides</code>, <code>skewThresholdsFor</code> and the compile-time checks. Everything else sits under <code>packages/core/src/detectors/</code>:</p><table tabindex="0"><thead><tr><th>Module</th><th>Holds</th></tr></thead><tbody><tr><td><code>&lt;type&gt;/detect.ts</code></td><td>one folder per detector, named for its type in kebab-case (<code>slow-host/</code>): the <code>DETECTORS</code> entry, its finding members and <code>Emits</code> (with the type-only <code>emits</code> export), <code>evidenceKeys</code> and <code>idDiscriminators</code>. <code>config-audit/</code> holds the three <code>configAudit</code> entries and <code>broadcast-sizing/</code> the entry that emits <code>underBroadcast</code> and <code>overBroadcast</code></td></tr><tr><td><code>&lt;type&gt;/presentation.ts</code></td><td>the folder&#39;s <code>FINDING_PRESENTATION</code> row</td></tr><tr><td><code>index.ts</code></td><td>every folder&#39;s <code>detect.ts</code> once, in render order, with its finding-member re-exports</td></tr><tr><td><code>presentations.ts</code></td><td>every folder&#39;s <code>presentation.ts</code> once</td></tr><tr><td><code>presentation-shared.ts</code></td><td>the helpers several presentation rows share</td></tr><tr><td><code>finding-bases.ts</code></td><td>the finding columns every member extends (<code>FindingCore</code>, <code>NumericFinding</code>, <code>TextFinding</code>) and the plan-finding evidence</td></tr><tr><td><code>speculation.ts</code></td><td>the speculation rule <code>slowHost</code>, <code>straggler</code> and <code>speculationWaste</code> share</td></tr><tr><td><code>types.ts</code></td><td><code>DetectorCtx</code>, <code>DetectorStage</code>, <code>DetectorConfigTarget</code>, <code>DetectorThresholds</code>, <code>DetectorScope</code>, <code>Detector</code>, <code>SkewThresholds</code> and the other detector-facing types</td></tr><tr><td><code>define.ts</code></td><td>the <code>define*Detector</code> helpers and <code>mergeThresholds</code>, which resolves a caller&#39;s threshold overrides</td></tr><tr><td><code>conf.ts</code></td><td>effective-conf readers: <code>effectiveConf</code>, <code>queryApp</code>, <code>stageApp</code>, <code>loggedAs</code>, <code>dynamicAllocationOff</code>, <code>hasStageOutsideSql</code></td></tr><tr><td><code>fixes.ts</code></td><td>fix helpers several entries share: <code>switchFix</code>, <code>setConfUnlessLogged</code>, <code>dynamicAllocationFix</code>, <code>idleCapacityFix</code></td></tr><tr><td><code>confidence.ts</code></td><td>the confidence scalers each entry&#39;s <code>detect()</code> calls</td></tr><tr><td><code>plan-shape.ts</code></td><td><code>computePlanShapes</code>, <code>normalizeDetail</code>, <code>findCompositeCandidates</code>, <code>findDuplicateSubtrees</code> and the Spark file-metric names</td></tr><tr><td><code>plan-attribution.ts</code></td><td><code>sqlStageIds</code>, <code>unionStageIds</code>, <code>isExecutionWideStageIds</code></td></tr><tr><td><code>plan-joins.ts</code></td><td>the join-side shuffle and broadcast-candidate readers</td></tr><tr><td><code>runtime-floor.ts</code>, <code>tail.ts</code></td><td>the runtime floor, <code>computeSkewRatio</code>, the tail claim and verdict that <code>skew</code> and <code>straggler</code> share</td></tr><tr><td><code>skew-fix.ts</code>, <code>partition.ts</code></td><td>the skew advice and the partition-count advice several entries share</td></tr><tr><td><code>units.ts</code></td><td><code>MB</code> and <code>GB</code></td></tr></tbody></table><p>Only <code>analyzer.ts</code> and <code>detector-catalog.ts</code> import <code>detectors.ts</code> by value. Any other module reads <code>DETECTORS</code>, <code>ENTRY_BY_TYPE</code> and <code>detectorCatalog()</code> from <code>detector-catalog.ts</code>, takes helpers from the <code>detectors/</code> modules, and imports types from <code>detectors.ts</code> with <code>import type</code>. The <code>no-detectors-value-import</code> rule of <code>npm run lint:structure</code> fails on any other value import, and <code>npm run lint</code> fails on a <code>detectors/</code> module over 1200 lines. The helpers import no entry, so a module in <code>detectors/</code> never depends on the list built from them.</p><h2 id="confidence-disclosure" tabindex="-1">Confidence disclosure <a class="header-anchor" href="#confidence-disclosure" aria-label="Permalink to &quot;Confidence disclosure&quot;">​</a></h2><p>A <code>Finding</code> may carry <code>confidence: &#39;low&#39; | &#39;medium&#39; | &#39;high&#39;</code> plus a <code>validationRequired</code> string. <code>RowStatusCluster</code> (<code>src/view/RowStatusCluster.tsx</code>) renders it on widget rows (the verdict&#39;s steps print their own &quot;verify before acting&quot; line), gated to Advanced density: a plain &quot;&lt;confidence&gt; confidence&quot; badge whose tooltip carries the full <code>validationRequired</code> text. A finding with no <code>confidence</code> field renders identically to a fully-validated one, so every detector whose thresholds are our own unvalidated noise floor (listed in <a href="./detector-contract/threshold-tables.html#threshold-sources">Threshold sources</a>) should set both fields, not just the ones that happen to already have <code>RowStatusCluster</code> wired into their widget. <code>skew</code>, <code>straggler</code>, and <code>gc</code> set <code>confidence</code> for exactly this reason: their runtime-floor thresholds carry the same kind of unvalidated-noise-floor caveat <code>coreLocality</code>, <code>autoscalingChurn</code>, and <code>memoryUtilization</code>&#39;s <code>wasteModel</code> variant already disclose. None of these hardcode a single confidence value: each scales <code>&#39;low&#39; | &#39;medium&#39; | &#39;high&#39;</code> off how far the finding sits past its own detector&#39;s threshold, via a small named helper in <code>detectors/confidence.ts</code> (e.g. <code>skewConfidence</code>, <code>coreLocalityConfidence</code>, <code>cachingReuseConfidence</code>) rather than an inline literal.</p><h2 id="the-fixeffort-field" tabindex="-1">The <code>fixEffort</code> field <a class="header-anchor" href="#the-fixeffort-field" aria-label="Permalink to &quot;The `fixEffort` field&quot;">​</a></h2><p>Each <code>Detector</code> entry also carries <code>fixEffort: &#39;config&#39; | &#39;code&#39; | &#39;rearchitect&#39;</code>, alongside <code>order</code> and <code>thresholds</code>: a rough estimate of how much work resolving the finding takes.</p><p>No view reads it: the ranking <code>FixTheseFirst</code> (<code>src/view/widgets/FixTheseFirst.tsx</code>) renders is computed in core by <code>interpretRun</code> (<code>rankedRollup</code>/<code>rankFindings</code> in <code>packages/core/src/recommendation-rollup.ts</code>), by estimate tier and impact, never by <code>fixEffort</code>. See <a href="./widget-rendering.html#widget-rendering-order">Widget rendering order</a> for how it ranks findings.</p><p>Two shared helpers back multiple detectors and reports. <code>packages/core/src/plan-tree-walk.ts</code>&#39;s <code>walkPlanTree(root, visit, {dedupe})</code> is the iterative pre-order plan-tree traversal used by the <code>detectors/</code> modules, <code>plan-summary.ts</code>, <code>plan-duration-attribution.ts</code>, <code>plan-dot.ts</code> and <code>plan-graph-model.ts</code>. <code>packages/core/src/core-count.ts</code> holds the shared core-count logic. Its <code>computePeakConcurrentCores</code>/<code>computePeakConcurrentExecutorCount</code> sweeps back the cost detector folders, <code>efficiency-model.ts</code>&#39;s zero-skew floor and the cluster size the <code>utilization</code> finding reports. The idle capacity the <code>utilization</code> and <code>memoryUtilization</code> entries, <code>efficiency-model.ts</code> and <code>wasted-core-hours.ts</code> measure against is the allocation (<code>allocatedCoreMs()</code> in <code>allocation.ts</code>, cores × time each executor was alive), so the Scorecard&#39;s Unused core time and the verdict&#39;s idle figure share one capacity that never exceeds what the run held. <code>computeTotalCores(app, executorsAdded)</code>, used only by <code>scaling-sim.ts</code>, sums every <code>ExecutorAdded</code> event with no regard for overlap, so under executor churn (spot preemption, <code>dynamicAllocation</code> replacement) it double-counts a churned executor&#39;s capacity against its replacement&#39;s; the peak-concurrent sweeps don&#39;t.</p><h2 id="effective-configuration" tabindex="-1">Effective configuration <a class="header-anchor" href="#effective-configuration" aria-label="Permalink to &quot;Effective configuration&quot;">​</a></h2><p>A detector that reads or suggests a Spark property resolves it through <code>effectiveSparkConf()</code> (<code>packages/core/src/spark-conf.ts</code>), which layers three sources: the SQL execution&#39;s <code>modifiedConfigs</code> (the session settings that differ from the SparkContext&#39;s, as <code>spark.conf.set</code> leaves them), the app&#39;s Spark Properties, then Spark&#39;s default for the run&#39;s version. It returns the value and the layer it came from (<code>query</code>, <code>app</code> or <code>default</code>). <code>sparkConfDefault()</code> is the version table alone; its entries are read from Spark&#39;s <code>SQLConf.scala</code> and <code>config/package.scala</code> at the release tags, and a property whose default depends on the cluster or on another property has no entry. Add a property to the table only with the release that introduced each of its defaults, and a per-version test.</p><p>A detector scoped to one SQL execution (<code>skew</code>, <code>straggler</code>, <code>shuffle</code>, <code>partitionSizing</code>, <code>underBroadcast</code>, <code>overBroadcast</code>, <code>pythonUdf</code>) passes that execution&#39;s <code>modifiedConfigs</code>: <code>detectors/conf.ts</code>&#39;s <code>stageApp()</code> and <code>queryApp()</code> return the app with them applied, so the helpers that take an app (<code>effectiveConf</code>, <code>loggedAs</code>, <code>switchFix</code>) need no second argument. Run-wide detectors use the app as logged. The frozen detection thresholds do not follow a per-query setting; only the advice does.</p><p>The skew family&#39;s advice for a stage that reads a shuffle feeding a join comes from <code>diagnoseJoinSkew</code> in <code>aqe-skew.ts</code>, which walks the execution&#39;s final plan against the conditions Spark&#39;s <code>OptimizeSkewedJoin</code> checks (join shape, join type, thresholds, extra shuffle) and reads the thresholds through the same effective conf. It returns <code>null</code> when the plan cannot say, and the detector then keeps the general advice. A new case is a new <code>AqeSkewCase</code>, a row in <code>AQE_SKEW_GENERIC</code> (<code>detectors/presentation-shared.ts</code>) and a row in the user guide&#39;s <code>SKEW</code> table.</p><h2 id="finding-ids" tabindex="-1">Finding ids <a class="header-anchor" href="#finding-ids" aria-label="Permalink to &quot;Finding ids&quot;">​</a></h2><p>A finding&#39;s <code>id</code> is a stable hash of its <code>type</code>, its location (stage, SQL execution or audited config property), <code>metric</code>, <code>value</code> and the per-type discriminator fields in <code>ID_DISCRIMINATORS</code> (<code>packages/core/src/finding-meta.ts</code>, assembled from each folder&#39;s <code>idDiscriminators</code>): the fields that tell apart sibling findings sharing a location and metric. Reordering or renaming a discriminator slot changes every id and needs an <code>EVIDENCE_SCHEMA_VERSION</code> bump, and so does adding one to <code>DISCRIMINATOR_SLOTS</code>. A new slot goes in <code>APPENDED_SLOTS</code> instead: those are joined after the fixed slots only for the types that list them, so other ids stay the same. <code>joinKeyCast</code> uses <code>planNodeIds</code> there, since two cast joins of one operator in one execution can share a value.</p><h2 id="cross-detector-suppression" tabindex="-1">Cross-detector suppression <a class="header-anchor" href="#cross-detector-suppression" aria-label="Permalink to &quot;Cross-detector suppression&quot;">​</a></h2><p>An entry may name another entry&#39;s <code>type</code> in <code>suppressedBy</code>. Once every detector has run, <code>analyze()</code>&#39;s <code>applySuppression()</code> drops each of that entry&#39;s findings on a stage where the named detector emitted a finding. It reads the unsuppressed findings, so neither the two entries&#39; declaration order nor the order suppressions apply in changes the result, and <code>order</code> stays a display field only. A compile-time check in <code>detectors.ts</code> (<code>SuppressorsAreDetectors</code>) fails when <code>suppressedBy</code> names no entry.</p><p><code>stageSlowness</code> sets <code>suppressedBy: &#39;slowHost&#39;</code>: a stage <code>slowHost</code> already explains needs no generic &quot;this stage is slow&quot; finding. Suppression follows what <code>slowHost</code> actually emitted, so a run whose <code>slowHost</code> thresholds are tuned so it can&#39;t fire gets its <code>stageSlowness</code> findings back. The mechanism is deliberately minimal (same-stage, one named suppressor per entry), not a general dependency graph. <code>auditConfig()</code> doesn&#39;t apply it, since no <code>scope:&#39;config&#39;</code> entry sets <code>suppressedBy</code>.</p><h2 id="tuning-thresholds" tabindex="-1">Tuning thresholds <a class="header-anchor" href="#tuning-thresholds" aria-label="Permalink to &quot;Tuning thresholds&quot;">​</a></h2><p><code>analyze()</code>&#39;s eighth argument is <code>{ thresholds?: ThresholdOverrides }</code>: per-entry overrides keyed by entry <code>type</code>, each a partial of that entry&#39;s own <code>thresholds</code>. Omitted, every entry runs its defaults; the dashboard never passes it. The CLI&#39;s and the MCP server&#39;s <code>--thresholds &lt;file&gt;</code> read a JSON file of that shape (<code>packages/core/src/cli/threshold-config.ts</code>) and validate it with <code>parseThresholdOverrides()</code> (<code>packages/core/src/threshold-overrides.ts</code>), which refuses an unknown detector or threshold, a negative or non-numeric value, a tier table of a different length or out of ascending order, an entry with no thresholds (<code>stageFailed</code>, <code>incompleteRun</code>), and any <code>configAudit</code> (config-scope) override: those checks compare against Spark&#39;s own defaults, so there is nothing to tune. A file that can&#39;t be read or parsed refuses the run the same way. The <a href="./../../user-guide/getting-started/tuning-thresholds.html#tuning-detector-thresholds">user guide</a> documents the file.</p><p>A finding from an entry whose overrides move a threshold off its default carries <code>tunedThresholds</code> (<code>{ &lt;name&gt;: { value, default } }</code>), and once its estimate is attached the analyzer appends a caveat to its <code>validationRequired</code> naming the tuned values. When the finding has an estimate figure (wall-clock or raw waste), the caveat adds that impact estimates are calibrated against the default thresholds (see <a href="./impact-estimation.html">Impact estimation</a>), so its estimate is unvalidated; an informational finding gets the label alone. An override equal to the default labels nothing. Tuning a <code>suppressedBy</code> target changes which of the suppressed entry&#39;s findings survive, so those findings carry the suppressor&#39;s tuned thresholds too, named <code>&lt;suppressor&gt;.&lt;name&gt;</code> (e.g. <code>slowHost.minHosts</code> on <code>stageSlowness</code>). <code>straggler</code> has no <code>suppressedBy</code> but judges a tail with <code>skew</code>&#39;s resolved thresholds (<code>DetectorCtx.skewThresholds</code>), so its findings carry <code>skew</code>&#39;s tuned thresholds the same way (<code>THRESHOLD_DEPENDENCY</code> in <code>threshold-overrides.ts</code>). Only that one link is followed. The evidence report repeats the label on the finding row, the clean check, the <code>detectors</code> catalog row (whose <code>thresholds</code> are then the effective ones) and in <code>summary.tunedThresholds</code>; see <a href="./worker-protocol/evidence-report.html#portable-evidence-report">Portable evidence report</a>.</p><p>A tuned <code>floorPctWarn</code>/<code>floorPctCrit</code> on <code>skew</code> or <code>straggler</code> also grades that entry&#39;s own findings in <code>gradeFinding</code> (<code>impact-band.ts</code>); every other finding keeps the run-wide default floors. <code>--max-skew</code> recomputes the ratio with the run&#39;s effective <code>minTasksForP95</code>, so the budget measures the same ratio the skew finding reports. Caveat text that names a threshold (<code>gc</code>, <code>skew</code>, <code>straggler</code>, <code>memoryUtilization</code>, <code>coreLocality</code>) and the <code>broadcastSizing</code> over-broadcast recommendation state the value the detector ran with. The HTML export still renders the default-threshold analysis.</p><h2 id="detector-catalog" tabindex="-1">Detector catalog <a class="header-anchor" href="#detector-catalog" aria-label="Permalink to &quot;Detector catalog&quot;">​</a></h2><p><code>buildDetectorCatalog()</code> (<code>packages/core/src/detector-listing.ts</code>) returns one <code>DetectorCatalogRecord</code> per emitted finding type, with no run needed. A record joins the type&#39;s <code>DETECTORS</code> entries with its <code>FINDING_PRESENTATION</code> row (the folder&#39;s <code>presentation.ts</code>), which also holds the outcome <code>family</code> (<code>DETECTOR_FAMILIES</code> gives the order and labels), a one-sentence <code>pitch</code> with no figures or names, and the <code>region</code> marker. The fields are listed in the <a href="./../../user-guide/mcp-tools/list-detectors.html"><code>list_detectors</code> reference</a>.</p><p>The <code>list_detectors</code> MCP tool and the <code>sparkforensics-analyze detectors</code> command read the same builder, so they state the same default thresholds, docs and gates. The listing reads the entries through <code>detector-catalog.ts</code>, which also holds <code>detectorCatalog()</code>, the per-entry metadata the evidence report records.</p><p>The docs site&#39;s <code>/docs/detectors/</code> pages are generated from the catalog by <code>scripts/build-detector-pages.mjs</code> (see <a href="./../development-setup.html#generated-and-vendored-files">Generated and vendored files</a>). Every output a page shows is captured from a real run during the script: an in-memory <code>list_detectors</code> and <code>get_finding_documentation</code> call, and <code>runDetectorsCommand([&#39;--type&#39;, type, &#39;--format&#39;, &#39;md&#39;])</code>. The example finding is the dashboard&#39;s own widget in a frame: <code>dev/detector-examples.json</code> names the finding and <code>dev/detector-example-runs.json</code> holds its run, described in <a href="./../testing.html#detector-examples">Detector examples</a>. The frame is the example app (<code>docs-widget.html</code>, <code>src/docs-widget/</code>), built from the HTML export&#39;s graph and guard. It draws the finding as the dashboard does, as a verdict step when the run&#39;s verdict leads with it and as a Findings row otherwise, with its evidence panel open, and without the &quot;Next step&quot; header or the step labels (<code>StepCodesShownContext</code>) that tie a step to the rest of the dashboard. The docs site and the app&#39;s frames exchange only the typed messages in <code>src/docs-widget/frame-messages.ts</code>, never each other&#39;s documents: the page puts the first theme in the frame&#39;s <code>theme</code> query parameter and posts a <code>theme</code> message when it changes, and the frame posts its <code>height</code>. A framed docs page posts <code>escape</code> for an Esc it does not consume, which closes the app&#39;s docs panel. Each receiver checks <code>event.origin</code> and <code>event.source</code>. Adding a finding type adds its page; the type needs a <code>FINDING_PRESENTATION</code> row with a <code>pitch</code> and <code>family</code>, and <code>tests/detector-pages.test.js</code> fails until a log fires it.</p>',41)])])}const f=o(s,[["render",r]]);export{u as __pageData,f as default};
